# PORTABLE MODE DECIDES THIS AT IMPORT, not in main().
#
# MEASURED 1 Sep, and it cost an encode: main() sets CONFIG_PATH to the app
# folder's config when portable_mode() is true, and everything that imports
# this module as a LIBRARY never runs main(). So a measurement script, or
# anything else driving the engine directly, silently read
# %APPDATA%\DiscRipper\config.toml - which on this machine says x265 on the
# CPU with compress off, where the config the app is actually run with says
# av1 on the GPU. The film came out right and every setting about it was
# wrong, and it would have taken hours instead of minutes.
#
# --config still wins, and main() still applies it; this only fixes the
# default for callers that never get there.
CONFIG_PATH = (Path(CONFIG_ENV) if CONFIG_ENV
               else (SCRIPT_DIR / "config.toml" if portable_mode()
                     else CONFIG_PATH_DEFAULT))


def console_window():
    """HWND of the classic console window, or 0.

    0 does not mean "no console": a modern terminal (Windows Terminal, the VS
    Code terminal, anything using a pseudoconsole) has no console window at all,
    so this is only good for deciding whether a window *can* be hidden."""
    try:
        return ctypes.windll.kernel32.GetConsoleWindow()
    except Exception:
        return 0


def console_processes():
    """How many processes share this console; 0 when there is no console."""
    try:
        arr = (ctypes.wintypes.DWORD * 16)()
        return ctypes.windll.kernel32.GetConsoleProcessList(arr, 16)
    except Exception:
        return 0


def has_console():
    """True when a terminal is attached, pseudoconsole or not."""
    return console_processes() > 0 or bool(console_window())


def console_is_ours():
    """True when this console exists only to run us.

    Hiding a console the user is working in would take their shell away, so
    check who else is attached: a double-clicked launcher gives us cmd.exe plus
    this interpreter, while a console we were typed into also has their shell."""
    n = console_processes()
    return 0 < n <= 2


def hide_console():
    h = console_window()
    if h and console_is_ours():
        ctypes.windll.user32.ShowWindow(h, 0)   # SW_HIDE
        return True
    return False


def show_console():
    h = console_window()
    if h:
        ctypes.windll.user32.ShowWindow(h, 5)   # SW_SHOW


def _gui_relaunch(ns=None):
    """Re-exec the GUI under pythonw.exe, which has no console at all.

    Hiding our own console is the fallback, but it can only ever hide a window
    the user didn't want; relaunching detached leaves their terminal free and
    puts no stray console in the taskbar."""
    exe = Path(sys.executable)
    if exe.stem.lower().endswith("w"):
        return False                      # already windowless
    wexe = exe.with_name(exe.stem + "w" + exe.suffix)
    if not wexe.exists():
        return False
    cmd = [str(wexe), str(SCRIPT_DIR / "discripper.py"), "gui", "--no-relaunch"]
    if CONFIG_PATH != CONFIG_PATH_DEFAULT:
        cmd += ["--config", str(CONFIG_PATH)]
    prof = getattr(ns, "profile", None)
    if prof:
        cmd += ["--profile", prof]
    DETACHED_PROCESS = 0x00000008
    CREATE_NO_WINDOW = 0x08000000
    try:
        subprocess.Popen(cmd, creationflags=DETACHED_PROCESS | CREATE_NO_WINDOW,
                         close_fds=True)
    except OSError as e:
        log(f"GUI relaunch failed: {e}")
        return False
    return True


def launch_gui(settings, ns=None):
    """Open the graphical front end. It drives this same module, so the CLI and
    the window share one config file and one set of ripping code paths."""
    if str(sys.platform) != "win32":
        err("The GUI is Windows-only, like the rest of DiscRipper.")
        return 2
    try:
        import tkinter  # noqa: F401  (probe: embeddable Python omits tkinter)
    except Exception:
        err("This Python has no tkinter, so the GUI cannot open.")
        info("The bundled 'embeddable' Python deliberately ships without it. "
             "Install a normal Python (winget install Python.Python.3.12) and "
             "run the GUI with that, or use the text wizard - it exposes every "
             "option too.")
        return 2
    try:
        import discripper_gui
    except ImportError as e:
        err(f"discripper_gui.py could not be imported: {e}")
        info(f"It should sit next to discripper.py in {SCRIPT_DIR}")
        return 2
    if not getattr(ns, "no_relaunch", False) and has_console():
        if _gui_relaunch(ns):
            info("DiscRipper window opened - no terminal behind it.")
            return 0
        log("windowless relaunch unavailable; hiding the console instead")
    hidden = hide_console()
    try:
        return discripper_gui.run(sys.modules[__name__], settings)
    finally:
        if hidden:
            show_console()


def main(argv=None):
    global USE_COLOR, VERBOSE, ASSUME_YES, DRY_RUN, CONFIG_PATH
    # Under pythonw (the windowless GUI re-exec) there is no console, so these
    # are None and any print() would raise. Everything still reaches the log.
    if sys.stdout is None:
        sys.stdout = open(os.devnull, "w", encoding="utf-8")
    if sys.stderr is None:
        sys.stderr = sys.stdout
    argv = list(sys.argv[1:] if argv is None else argv)
    if not argv or argv[0].startswith("-") and argv[0] not in ("-h", "--help", "--version"):
        argv.insert(0, "wizard")
    parser = build_parser()
    ns = parser.parse_args(argv)

    USE_COLOR = sys.stdout.isatty() and not getattr(ns, "no_color", False) \
        and not os.environ.get("NO_COLOR")
    if USE_COLOR:
        _enable_ansi()
    try:
        sys.stdout.reconfigure(encoding="utf-8", errors="replace")
    except Exception:
        pass
    VERBOSE = getattr(ns, "verbose", 0)
    ASSUME_YES = getattr(ns, "yes", False)
    DRY_RUN = getattr(ns, "dry_run", False)
    if getattr(ns, "config", None):
        CONFIG_PATH = Path(ns.config)
    elif portable_mode():
        CONFIG_PATH = SCRIPT_DIR / "config.toml"

    if sys.version_info < (3, 11):
        err(f"Python 3.11+ required (found {sys.version.split()[0]}). "
            "Install with:  winget install Python.Python.3.12")
        return 2

    settings = load_config(CONFIG_PATH)
    profile = getattr(ns, "profile", None) or sget(settings, "general.profile", "")
    apply_profile(settings, profile)

    cmd = ns.command or "wizard"
    try:
        if cmd == "gui":
            return launch_gui(settings, ns)
        if cmd == "wizard":
            return wizard(settings) or 0
        if cmd == "rip":
            if not (screen_flag_ok(ns) and quality_flag_ok(ns)):
                return 2
            apply_rip_flags(settings, ns)
            if getattr(ns, "from_source", None):
                disc = source_disc(ns.from_source)
                if disc is None:
                    return 1
                header(f"From a copy, not a disc: {ns.from_source}")
                # The same finishing every other rip gets. Skipping post_rip
                # here meant a rip-from-copy - the one whose provenance
                # matters most, because the disc may be long gone - got no
                # checksum, no sidecar, no finished alert and no shutdown.
                riplog_start(label=prettify_label(disc.get("label")) or "copy",
                             kind=disc.get("type") or "", drive="",
                             mode="from", settings=settings)
                riplog("disc", **{k: disc.get(k) for k in
                                  ("type", "label", "detect", "fs_size",
                                   "source")})
                r = do_rip_video(settings, None, disc)
                post_rip(settings, None, disc, r)
                return 0 if r else 1
            result = do_rip(settings)
            return 0 if result else 1
        if cmd == "batch":
            if not (screen_flag_ok(ns) and quality_flag_ok(ns)):
                return 2
            apply_rip_flags(settings, ns)
            batch_mode(settings)
            return 0
        if cmd == "auto":
            if not (screen_flag_ok(ns) and quality_flag_ok(ns)):
                return 2
            apply_rip_flags(settings, ns)
            for dest, key in (("auto_titles", "general.auto_titles"),
                              ("auto_naming", "general.auto_naming"),
                              ("on_failure", "general.auto_on_failure"),
                              ("max_titles", "video.max_titles"),
                              ("max_length", "video.max_length"),
                              ("stop_after", "general.auto_stop_after"),
                              ("wait_minutes", "general.auto_wait_minutes")):
                val = getattr(ns, dest, None)
                if val is not None:
                    sset(settings, key, val)
            if getattr(ns, "no_report", False):
                sset(settings, "general.auto_report", False)
            auto_rip_loop(settings)
            return 0
        if cmd == "info":
            if getattr(ns, "drive", None):
                sset(settings, "general.drive", ns.drive)
            return cmd_info(settings)
        if cmd == "riplog":
            return cmd_riplog(settings, ns)
        if cmd == "damage":
            return cmd_damage(settings, ns)
        if cmd == "image":
            return cmd_image(settings, ns)
        if cmd == "retry":
            return cmd_retry(settings, ns)
        if cmd == "salvage":
            return cmd_salvage(settings, ns)
        if cmd == "remux":
            return cmd_remux(settings, ns)
        if cmd == "join":
            return cmd_join(settings, ns)
        if cmd == "split":
            return cmd_split(settings, ns)
        if cmd == "tracks":
            return cmd_tracks(settings, ns)
        if cmd == "chapters":
            return cmd_chapters(settings, ns)
        if cmd == "gaps":
            return cmd_gaps(settings, ns)
        if cmd == "bridge":
            return cmd_bridge(settings, ns)
        if cmd == "drives":
            drives = list_drives()
            if not drives:
                err("No optical drives found.")
                return 1
            for d in drives:
                state = "disc present" if (d["loaded"] or disc_present(d["letter"])) else "empty"
                say(f"  {d['letter']}:  {d['desc']}  [{state}]"
                    + (f"  label: {d['label']}" if d["label"] else ""))
            return 0
        if cmd == "doctor":
            return cmd_doctor(settings)
        if cmd == "setup":
            return cmd_setup(settings)
        if cmd == "bundle":
            return cmd_bundle(settings)
        if cmd == "key":
            if getattr(ns, "status", False):
                st = makemkv_key_status(settings)
                say(f"  MakeMKV key: {st['state'].upper()}"
                    + (f" - {st['message']}" if st["message"] else ""))
                return 0 if st["state"] == "ok" else 1
            key = getattr(ns, "set_key", None)
            if key is None and getattr(ns, "fetch", False):
                key = fetch_beta_key()
                if not key:
                    return 1
                ok(f"Found key: {key[:18]}...{key[-6:]}")
            return cmd_makemkv_key(settings, key=key,
                                   fetch=getattr(ns, "fetch", False),
                                   save=not getattr(ns, "no_save", False))
        if cmd == "encode":
            if not (screen_flag_ok(ns) and quality_flag_ok(ns)):
                return 2
            # the mode first, so an explicit flag beside it still wins
            picked = next((m for m in MODES if getattr(ns, m, False)), None)
            if picked:
                apply_mode(settings, picked)
                for line in MODE_NOTES.get(picked, ()):
                    say(col("    - " + line, C.DIM))
            for dest in ("vcodec", "quality", "vpreset", "hw", "max_height",
                         "acodec", "abitrate", "extra_ffmpeg",
                         "trim_bars", "screen", "fit"):
                val = getattr(ns, dest, None)
                if val is not None:
                    sset(settings, RIP_FLAG_MAP.get(dest) or f"video.{dest}", val)
            if getattr(ns, "no_keep_original", False):
                sset(settings, "video.keep_original", False)
                # keep_original only applies when the caller owns the input -
                # the rip flow, and the wizard that asks in so many words.
                # The command line is deliberately not among them, so this
                # flag cannot remove anything; saying so beats a flag that
                # parses and silently does nothing.
                warn("--no-keep-original has no effect on 'encode': the "
                     "command line never deletes the files you point it at. "
                     "Use --recycle-originals or --delete-originals, which "
                     "remove an original only after its encode has been read "
                     "back and found sound.")
            return cmd_encode_batch(
                settings, ns.input,
                not getattr(ns, "no_recurse", False),
                getattr(ns, "force", False),
                "recycle" if getattr(ns, "recycle_originals", False)
                else "delete" if getattr(ns, "delete_originals", False)
                else None)
        if cmd == "alerts":
            if getattr(ns, "test_notify", False):
                return cmd_test_notify(settings)
            master = sget(settings, "alerts.enabled", True)
            say(f"  Alerts master switch: {'ON' if master else 'OFF'}")
            say(f"  Popup style: {sget(settings, 'general.notify_style', 'auto')}"
                f"  (notifications {'on' if sget(settings, 'general.notify', True) else 'off'})")
            say(f"  Stall threshold: {sget(settings, 'alerts.stall_seconds', 300)}s"
                " without progress"
                f"; silence budget before first progress: "
                f"{sget(settings, 'alerts.startup_grace_seconds', 900)}s")
            say(f"  Progress cue: every "
                f"{sget(settings, 'alerts.progress_every_percent', 10)}%")
            who = str(sget(settings, "alerts.voice", "") or "Windows default")
            say(f"  Volume: {sget(settings, 'alerts.volume', 100)} of 100"
                f"   Voice: {who} at rate "
                f"{sget(settings, 'alerts.voice_rate', 0)}")
            for ev, label in ALERT_EVENTS:
                snd = sget(settings, f"alerts.sound_{ev}", "")
                say(f"    {label:<32} {sget(settings, f'alerts.on_{ev}', 'none'):<8} {snd}")
                if is_voice(snd):
                    say(col(f"    {'':<41} \"{sample_line(settings, ev)}\"",
                            C.DIM))
                if getattr(ns, "test", False):
                    if not preview_alert(settings, ev):
                        warn(f"    could not play: {snd}")
                    time.sleep(3.0 if is_voice(snd) else 1.4)
            if getattr(ns, "test", False):
                stop_speaking()     # let the last line finish before we exit
            return 0
        if cmd == "mode":
            return cmd_mode(settings, getattr(ns, "which", None))
        if cmd == "fit":
            return cmd_fit(settings, ns.file, getattr(ns, "screen", None),
                           getattr(ns, "fit", None), getattr(ns, "sample", 0),
                           getattr(ns, "out", None))
        if cmd == "voices":
            return cmd_voices(settings, getattr(ns, "quiet", False))
        if cmd in ("eject", "close"):
            letter = getattr(ns, "drive", None)
            if letter:
                letter = letter.rstrip(":")
            else:
                drives = list_drives()
                letter = drives[0]["letter"] if drives else None
            if not letter:
                err("No optical drive found.")
                return 1
            eject_drive(letter, open_tray=(cmd == "eject"))
            return 0
        if cmd == "icon":
            return cmd_icon(settings, getattr(ns, "out", None))
        if cmd == "config":
            if ns.path:
                print(CONFIG_PATH)
                return 0
            if ns.reset:
                if ask_yn("Reset all settings to defaults?", False):
                    save_config(deepcopy(DEFAULTS), CONFIG_PATH)
                    ok("Config reset.")
                return 0
            if ns.edit:
                run(["notepad", str(CONFIG_PATH)], mode="capture", ignore_rc=True)
                return 0
            say(CONFIG_PATH.read_text(encoding="utf-8") if CONFIG_PATH.exists()
                else "(no config file yet - run once to create it)")
            return 0
    except KeyboardInterrupt:
        say("")
        # THE QUEUE FIRST. Anything not started is dropped - the person just
        # asked for the run to stop - but the job in hand is left to finish,
        # because it is holding a lossless file it is about to replace and
        # killing it there is the one outcome that loses the film. Dropped
        # BEFORE clean_scratch, so a queued job cannot start on a temporary
        # that is about to be deleted.
        _dropped = BG.forget_queued()
        if _dropped:
            info(f"Dropped {_dropped} background job(s) that had not started.")
        if not clean_scratch("you interrupted the run"):
            info("Nothing unfinished was left behind.")
        return 130
    except Cancelled:
        say("")
        _dropped = BG.forget_queued()
        if _dropped:
            info(f"Dropped {_dropped} background job(s) that had not started.")
        clean_scratch("the run was cancelled")
        return 130
    parser.print_help()
    return 0


if __name__ == "__main__":
    sys.exit(main())
